INSERT INTO questions (number, question, image, answer, group_id, user_id) VALUES 
(1, '¿Cuál es la diferencia conceptual fundamental entre una estimación puntual y una estimación por intervalos en la práctica clínica?', NULL, 'La estimación puntual ofrece un único valor (como la media de una muestra), mientras que la estimación por intervalos proporciona un rango de valores plausibles que reconoce la incertidumbre y el margen de error.', 1, 1),
(2, 'Si un artículo científico reporta un intervalo de confianza del 95% para la presión arterial media, ¿qué significa exactamente ese 95% en la práctica?', NULL, 'Significa que si el estudio se repitiera 100 veces bajo las mismas condiciones, aproximadamente 95 de esos intervalos construidos contendrían el verdadero parámetro de la población.', 1, 1),
(3, '¿Por qué la afirmación “hay un 95% de probabilidad de que la media real esté dentro de este intervalo calculado” es incorrecta?', NULL, 'Porque el parámetro poblacional es un valor fijo (no aleatorio), y el intervalo ya calculado o lo contiene o no lo contiene; lo correcto es hablar de nuestro nivel de confianza en el método.', 1, 1),
(4, '¿Cómo afectan el tamaño de la muestra y la variabilidad biológica de los datos al ancho de un intervalo de confianza?', NULL, 'Un mayor tamaño de muestra reduce el error estándar y estrecha el intervalo (más precisión); una mayor variabilidad biológica ensancha el intervalo debido a la mayor incertidumbre.', 1, 1),
(5, '¿Por qué en medicina se prefiere habitualmente un intervalo de confianza del 95% en lugar de uno del 99%?', NULL, 'Porque el 95% ofrece un equilibrio óptimo entre seguridad y precisión; un intervalo del 99% sería demasiado ancho y menos útil para tomar decisiones clínicas concretas.', 1, 1),
(6, '¿En qué condiciones prácticas de investigación en salud se debe utilizar la distribución Z frente a la distribución t de Student?', NULL, 'Se utiliza Z cuando se conoce la desviación estándar poblacional (σ), o cuando la muestra es muy grande; se utiliza t de Student cuando se desconoce σ y debe estimarse con la desviación estándar muestral (s).', 1, 1),
(7, '¿Qué características gráficas y estadísticas distinguen a la distribución t de Student de la distribución normal estándar (Z)?', NULL, 'La distribución t de Student tiene colas más pesadas y es más aplanada, lo que refleja la incertidumbre adicional al usar la desviación estándar de la muestra en lugar de la de la población.', 1, 1),
(8, '¿Qué papel juegan los grados de libertad (g.l. = n - 1) al trabajar con la distribución t de Student?', NULL, 'Determinan la forma específica de la curva t; a medida que el tamaño de la muestra y los grados de libertad aumentan, la distribución t se aproxima y se vuelve prácticamente idéntica a la normal estándar (Z).', 1, 1),
(9, '¿Por qué la tabla de la distribución t de Student solo muestra valores positivos a pesar de ser simétrica alrededor de cero?', NULL, 'Porque aprovecha la perfecta simetría de la distribución para ahorrar espacio, requiriendo que el investigador aplique la propiedad de simetría para obtener valores negativos en pruebas de cola izquierda.', 1, 1),
(10, '¿Qué implicancia clínica tiene el hecho de que el valor crítico de t sea ligeramente mayor que el de Z para un mismo nivel de confianza?', NULL, 'Genera intervalos de confianza un poco más anchos y umbrales de rechazo más estrictos, compensando adecuadamente la falta de conocimiento de la verdadera variabilidad poblacional.', 1, 1),
(11, '¿Qué representa analógicamente la hipótesis nula (H₀) en el contexto de una investigación sobre un nuevo fármaco o tratamiento médico?', NULL, 'Representa el statu quo o la ausencia de efecto (equivalente a asumir la inocencia en un juicio), indicando que el tratamiento no funciona o no genera cambios.', 1, 1),
(12, '¿Por qué se afirma en bioestadística que una prueba de hipótesis nunca demuestra que la hipótesis nula (H₀) sea verdadera?', NULL, 'Porque la estadística no da certezas absolutas; solo evalúa si hay suficiente evidencia empírica para rechazarla, o si los datos simplemente no permiten descartarla.', 1, 1);
INSERT INTO questions (number, question, image, answer, group_id, user_id) VALUES 
(13, '¿Cuál es la diferencia clínica y conceptual entre un error tipo I (alfa) y un error tipo II (beta) en una prueba de hipótesis?', NULL, 'El error tipo I consiste en concluir que un tratamiento funciona cuando no es así (falso positivo), mientras que el error tipo II consiste en descartar un tratamiento útil que sí funciona (falso negativo).', 2, 1),
(14, '¿Cómo se interpreta clínicamente el nivel de significación (α = 0.05) elegido comúnmente en los ensayos clínicos?', NULL, 'Representa la tolerancia máxima al error que el investigador acepta al declarar que un tratamiento es efectivo cuando en realidad no tiene ningún efecto (un 5% de riesgo de falso positivo).', 2, 1),
(15, '¿Por qué en medicina a veces es más crítico evitar un error tipo I y en otras ocasiones resulta más peligroso cometer un error tipo II?', NULL, 'Depende del contexto: se prioriza evitar el error tipo I en fármacos con graves efectos secundarios, y el error tipo II en enfermedades graves o epidemias donde se requiere no perder un tratamiento eficaz.', 2, 1),
(16, '¿Qué define conceptualmente la región crítica o de rechazo en una prueba de hipótesis estadística?', NULL, 'Es la "zona de alarma" o el límite de resultados tan poco habituales que, si el tratamiento no tuviera ningún efecto, casi nunca ocurrirían por pura suerte; si nuestro resultado cae ahí, decidimos que el tratamiento sí funciona.', 2, 1),
(17, '¿Qué diferencia existe en el planteamiento de una prueba de hipótesis de una cola (unilateral) frente a una de dos colas (bilateral)?', NULL, 'La prueba unilateral busca demostrar un cambio en una dirección específica (mayor o menor), mientras que la bilateral solo evalúa si existe diferencia en cualquier sentido (diferente de).', 2, 1),
(18, '¿Por qué la hipótesis nula (H₀) siempre debe incluir un signo de igualdad (=, ≤ o ≥) y la alternativa (H₁), en cambio, nunca lo incluye?', NULL, 'Porque H₀ representa un valor puntual o límite de referencia fijo que se pone a prueba, mientras que H₁ refleja la dirección del efecto o hipótesis de investigación que se quiere demostrar.', 2, 1),
(19, '¿Qué relación lógica y práctica existe entre un intervalo del confianza del 95% y una prueba de hipótesis bilateral con un nivel de significancia del 5%?', NULL, 'Son dos caras de la misma moneda: si el valor hipotético de referencia se encuentra fuera del intervalo de confianza al 95%, la prueba de hipótesis correspondiente rechaza H₀ con α = 0.05.', 2, 1),
(20, '¿Por qué no se deben aplicar pruebas de hipótesis estadísticas sobre variables cualitativas nominales puras que carecen de escala numérica?', NULL, 'Porque las pruebas de hipótesis inferenciales requieren parámetros numéricos o proporciones derivadas que posean una distribución muestral, y no categorías puras sin orden o magnitud.', 2, 1),
(21, '¿Qué implicancia clínica tiene para un médico encontrar que un valor de referencia diagnóstico (ej. 110 mg/dL) se encuentra completamente fuera del intervalo de confianza del 95% de sus pacientes?', NULL, 'Significa que hay una diferencia real y significativa; el valor de referencia no es un resultado plausible para ese grupo, lo que indica que no están alcanzando el objetivo terapéutico o clínico esperado.', 2, 1),
(22, '¿Por qué en un estudio clínico con una muestra pequeña (por ejemplo, n = 12) donde se desconoce la desviación estándar poblacional, es estadísticamente más correcto usar la distribución t de Student en lugar de Z?', NULL, 'Porque al estimar la desviación estándar con los datos de la propia muestra (s) se genera mayor incertidumbre; la distribución t de Student tiene colas más pesadas que corrigen esto y evitan dar falsas certezas.', 2, 1),
(23, '¿Por qué en la práctica médica se suele considerar "anormal" o digno de revisión un parámetro clínico que se encuentra a más de 2 desviaciones estándar de la media?', NULL, 'Porque estadísticamente el 95% de la población sana se concentra dentro del rango de dos desviaciones estándar alrededor de la media, por lo que valores más extremos ocurren en menos del 5% de las personas sanas.', 2, 1),
(24, '¿Qué limitaciones presenta el uso de muestras pequeñas al realizar inferencias estadísticas en la práctica médica diaria?', NULL, 'Las muestras pequeñas aumentan la incertidumbre, ensanchan los intervalos de confianza y reducen la potencia estadística, facilitando la ocurrencia de errores tipo II.', 2, 1);
INSERT INTO questions (number, question, image, answer, group_id, user_id) VALUES 
(25, '¿Cómo contribuyen los intervalos de confianza a evaluar si un tratamiento médico ha alcanzado un objetivo terapéutico específico?', NULL, 'Permiten comprobar si todo el rango plausible de valores se encuentra por debajo o por encima de un umbral clínico deseado, determinando si el objetivo se logró verdaderamente en la población.', 3, 1),
(26, '¿Por qué la inferencia estadística se considera el puente fundamental entre los hallazgos de una muestra y la toma de decisiones poblacionales?', NULL, 'Porque los médicos y investigadores nunca pueden estudiar a la totalidad de los pacientes, por lo que necesitan métodos rigurosos para generalizar con control del error hacia toda la comunidad.', 3, 1),
(27, '¿Qué implicancia tiene para la salud pública que un estudio clínico presente un intervalo de confianza extremadamente ancho?', NULL, 'Indica alta incertidumbre y falta de precisión en la estimación, lo que desaconseja basar guías clínicas o intervenciones importantes en dichos resultados.', 3, 1),
(28, '¿Por qué el uso conjunto de la estimación por intervalos y la prueba de hipótesis fortalece el rigor metodológico en la investigación en salud?', NULL, 'Porque la estimación mide la magnitud y precisión del efecto clínico, mientras que la prueba de hipótesis ayuda a decidir si dicho efecto es atribuible al tratamiento o al azar.', 3, 1),
(29, '¿Por qué la estadística inferencial no otorga certezas absolutas en medicina, sino herramientas de gestión de la incertidumbre?', NULL, 'Porque trabaja bajo condiciones de variabilidad biológica y con información parcial (muestras), buscando minimizar y cuantificar matemáticamente los riesgos de equivocarse.', 3, 1),
(30, '¿Qué diferencia metodológica clave existe al calcular un intervalo de confianza utilizando una desviación estándar conocida frente a una desconocida?', NULL, 'Cuando se conoce se utiliza el puntaje Z basado en la distribución normal, y cuando se desconoce se sustituye por la desviación estándar muestral empleando la distribución t de Student.', 3, 1),
(31, '¿Por qué se considera un error conceptual frecuente interpretar un intervalo de confianza asumiendo que el parámetro poblacional es una variable aleatoria?', NULL, 'Porque el parámetro poblacional es un valor fijo y constante aunque desconocido; lo que varía aleatoriamente de una muestra a otra es el intervalo calculado.', 3, 1),
(32, '¿Qué utilidad práctica aporta la regla de los grados de libertad en la selección de los valores críticos de la distribución t?', NULL, 'Permite ajustar de forma precisa la forma de la curva de acuerdo al tamaño exacto de la muestra analizada, volviéndose más exigente cuanto menor sea el número de observaciones.', 3, 1),
(33, '¿Cómo se interpreta el resultado de una prueba de hipótesis cuando el estadístico calculado cae dentro de la zona de aceptación?', NULL, 'Se concluye que no hay evidencia estadística suficiente para rechazar la hipótesis nula, por lo que se mantiene provisionalmente el statu quo clínico o la ausencia de efecto.', 3, 1),
(34, '¿Por qué es fundamental que un estudiante de medicina comprenda la diferencia entre un estadígrafo de muestra y un parámetro de población?', NULL, 'Porque evita confundir los datos descriptivos obtenidos directamente en un grupo de pacientes con la realidad oculta de toda la población que se pretende inferir y tratar.', 3, 1),
(35, '¿Qué sucede con los valores críticos de la distribución t de Student cuando el tamaño de la muestra supera las 100 observaciones?', NULL, 'Los valores críticos se asemejan y convergen casi por completo con los de la distribución normal estándar (Z), representado conceptualmente en las tablas por el valor infinito (∞).', 3, 1),
(36, '¿De qué manera el control riguroso del nivel de significancia (α) protege a los pacientes frente a la implementación de intervenciones terapéuticas inútiles?', NULL, 'Estableciendo un umbral estricto y predeterminado que frena la adopción de tratamientos basados en hallazgos casuales o falsos positivos derivados de la variabilidad muestral.', 3, 1);